/* Token Radar's theme: a dark radar room. Deep green-black canvas, a single emerald accent
   for the signal, amber for the money, and hairlines instead of boxes. Two radii, two families,
   and spacing steps carry the whole page. No network: system fonts only. */
:root {
  --canvas: #0b100e;
  --surface: #111916;
  --surface-2: #16211c;
  --surface-3: #1c2a24;
  --ink: #e9f1ec;
  --muted: #93a89d;
  --faint: #6b7f74;
  --border: #223029;
  --border-2: #2e4036;
  --accent: #34d399;
  --accent-dim: #1d7a58;
  --amber: #f2b544;
  --amber-dim: #8a6a25;
  --negative: #f27d72;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-num: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
  --step-7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
  text-wrap: pretty;
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 30px; line-height: 1.15; font-weight: 650; }
h2 { font-size: 19px; line-height: 1.25; font-weight: 650; }
h3 { font-size: 15px; line-height: 1.3; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--step-2) var(--step-4);
  background: var(--surface); border: 1px solid var(--border); z-index: 20;
}
.skip:focus { left: var(--step-4); top: var(--step-4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1280px; margin: 0 auto; padding: var(--step-4) var(--step-6) var(--step-7); }
.top {
  display: flex; align-items: center; justify-content: space-between; gap: var(--step-5);
  padding-bottom: var(--step-4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--step-3); }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(52, 211, 153, 0.15); flex: none; }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--step-2) var(--step-4); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.top-meta b { color: var(--ink); font-weight: 600; }

.lede { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr); gap: var(--step-6); padding: var(--step-5) 0 var(--step-4); }
.lede p { color: var(--muted); max-width: 62ch; margin-top: var(--step-2); }
.lede p b { color: var(--ink); font-weight: 600; }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: var(--step-2) var(--step-5); align-content: start; border-left: 1px solid var(--border); padding-left: var(--step-5); }
.fact { display: grid; gap: 2px; }
.fact b { font-family: var(--font-num); font-size: 17px; font-weight: 600; color: var(--ink); }
.fact b.amber { color: var(--amber); }
.fact span { color: var(--muted); font-size: 12px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--step-3); padding: var(--step-4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--step-1); }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 38px; padding: 0 var(--step-3); border: 1px solid var(--border-2); border-radius: var(--radius-control);
  background: var(--surface); min-width: 170px; color: var(--ink);
}
.field input { min-width: 260px; }
.field input::placeholder { color: var(--faint); }
.field select option { background: var(--surface); }
.tabs { display: flex; gap: var(--step-1); padding: 3px; border: 1px solid var(--border-2); border-radius: var(--radius-control); background: var(--surface); }
.tabs button { min-height: 32px; padding: 0 var(--step-3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: #08130d; font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
thead th { position: sticky; top: 0; background: var(--surface-2); z-index: 2; }
th, td { padding: 11px var(--step-3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
tbody tr:last-child td { border-bottom: 0; }
th { color: var(--muted); font-size: 12px; font-weight: 600; letter-spacing: 0.02em; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--step-1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--surface-2); }
tbody tr[data-selected="true"] { background: rgba(52, 211, 153, 0.08); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.rank-top { color: var(--amber); font-weight: 700; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--accent); }
.neg { color: var(--negative); }
.bar { width: 110px; height: 6px; border-radius: 3px; background: var(--surface-3); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--amber); }
.implied { display: flex; align-items: center; gap: var(--step-2); }
.implied .num { color: var(--amber); font-weight: 600; }
.status { display: inline-flex; align-items: center; gap: 6px; color: var(--accent); font-size: 12px; white-space: nowrap; border: 1px solid rgba(52, 211, 153, 0.35); border-radius: 999px; padding: 2px 8px; }
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
.status.live { color: var(--muted); border-color: var(--border-2); }
.status.live::before { background: var(--muted); }

.catbars { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.catbars h2 { margin-bottom: var(--step-1); }
.catbar { display: grid; grid-template-columns: 190px 1fr 150px; gap: var(--step-3); align-items: center; font-size: 13px; }
.catbar .cat { color: var(--ink); font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.catbar .track { height: 8px; border-radius: 4px; background: var(--surface-3); overflow: hidden; }
.catbar .track i { display: block; height: 100%; background: var(--accent); }
.catbar .val { font-family: var(--font-num); color: var(--muted); text-align: right; white-space: nowrap; }

.model { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--muted); overflow-wrap: anywhere; background: var(--canvas); border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--step-3) var(--step-4); }
.formula b { color: var(--amber); font-weight: 600; }
.model table { font-size: 13px; }
.model th, .model td { padding: 8px var(--step-3); }
.model td.num { color: var(--ink); }
.note { color: var(--muted); font-size: 13px; max-width: 78ch; }
.note b { color: var(--ink); font-weight: 600; }

.empty { padding: var(--step-7) var(--step-5); text-align: center; display: grid; gap: var(--step-3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 38px; padding: 0 var(--step-4); border: 1px solid var(--border-2); border-radius: var(--radius-control); background: var(--surface); color: var(--ink); }
.button.primary { background: var(--accent); border-color: var(--accent); color: #08130d; font-weight: 600; }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 10;
  background: var(--surface); border-left: 1px solid var(--border-2); padding: var(--step-5);
  overflow-y: auto; color: var(--ink);
}
.detail[hidden] { display: none; }
.detail { margin: 0 0 0 auto; max-height: 100%; }
.detail::backdrop { background: rgba(4, 8, 6, 0.6); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--step-4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 32px; min-height: 34px; padding: 0 var(--step-2); white-space: nowrap; border: 1px solid var(--border-2); border-radius: var(--radius-control); background: var(--surface); color: var(--ink); }
.detail h2 { margin-top: var(--step-1); }
.detail .sub { margin-top: var(--step-1); }
.detail-section { margin-top: var(--step-5); padding-top: var(--step-4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--step-2); }
.equation { display: grid; gap: var(--step-2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--step-3); }
.equation span { color: var(--muted); }
.equation b { color: var(--ink); font-weight: 600; }
.equation .total b { color: var(--amber); font-size: 15px; }
.comps { display: grid; gap: var(--step-1); font-size: 13px; }
.comps div { display: flex; justify-content: space-between; gap: var(--step-3); }
.comps span { color: var(--muted); }
.comps b { font-family: var(--font-num); font-weight: 600; }
.steps { margin: 0; padding-left: var(--step-5); display: grid; gap: var(--step-3); }
.steps li { padding-left: var(--step-1); }
.steps li::marker { color: var(--accent); font-family: var(--font-num); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }

.footer { margin-top: var(--step-6); padding-top: var(--step-4); border-top: 1px solid var(--border); color: var(--faint); font-size: 12px; display: grid; gap: var(--step-1); }
.footer b { color: var(--muted); font-weight: 600; }

@media (max-width: 900px) {
  .shell { padding: var(--step-4); }
  .lede { grid-template-columns: 1fr; gap: var(--step-4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--step-4); }
  .field input { min-width: 0; width: 100%; }
  .catbar { grid-template-columns: 130px 1fr 110px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
